fn inputs(p:&Path,name:&str)->Inputs{let manifest=p.join("logs/continuation-20261003").join(name);let b=fs::read(&manifest).unwrap();Inputs{project:p.into(),manifest,manifest_pin:BytePin{bytes:b.len()as u64,sha256:Sha256::digest(b).into()}}}
fn wait(mut f:impl FnMut()->bool){let end=Instant::now()+Duration::from_secs(60);while !f(){assert!(Instant::now()<end);thread::sleep(Duration::from_millis(2));}}
fn ready(p:&Path)->anyhow::Result<Runtime>{let mut rt=Runtime::start_with_menu_skin(inputs(p,"r486-map-binding.json"),inputs(p,"r498-native-menu-skin-binding.json"))?;wait(||{rt.poll();rt.page()==UiPage::Menu});Ok(rt)}
fn environment(v:&Value)->anyhow::Result<FixtureEnvironment>{FixtureEnvironment::synthetic(v["label"].as_str().unwrap(),v["code_page"].as_u64().unwrap()as u32,v["from_cd_registry_dword"].as_u64().unwrap()as u32,v["revision_word_source"].as_u64().unwrap()as u32,if v["special"].as_bool().unwrap(){FixtureVariant::Special{supplemental:bytes(&v["supplemental"])}}else{FixtureVariant::Normal})}
fn record(p:&Path,name:&str,details:Value,trace:&mut Vec<Value>){trace.push(json!({"name":name,"passed":true,"details":details}));fs::write(p.join("logs/continuation-20261003/r501-event-partial.json"),serde_json::to_vec_pretty(trace).unwrap()).unwrap();}
fn stage(rt:&mut Runtime,account:&[u8],password:&[u8])->anyhow::Result<()>{rt.open_source_login_form()?;let c=rt.source_login_control().unwrap();rt.edit_source_login_form(&c,account,password)?;let c=rt.source_login_control().unwrap();rt.stage_source_login_form(&c)?;Ok(())}
fn expect_server(stream:&mut TcpStream,v:&Value){let mut h=[0;2];stream.read_exact(&mut h).unwrap();let n=u16::from_le_bytes(h)as usize;assert!((3..=157).contains(&n));let mut frame=h.to_vec();frame.resize(n,0);stream.read_exact(&mut frame[2..]).unwrap();assert_eq!(frame,bytes(&v["wire"]));}
fn pending(rt:&Runtime,e:&Epoch,v:&Value)->anyhow::Result<()>{let t=rt.source_pending_write_ticket(e)?.unwrap();assert_eq!(rt.source_write_view(e,&t)?.bytes()?,bytes(&v["wire"]));assert_eq!(rt.source_send_snapshot().counter,v["after"].as_u64());Ok(())}
fn write_all(rt:&mut Runtime,e:&Epoch,cap:usize)->anyhow::Result<usize>{let counter=rt.source_send_snapshot().counter;let mut calls=0;loop{calls+=1;let p=rt.write_source_loopback_step(e,cap)?;assert_eq!(rt.source_send_snapshot().counter,counter);if matches!(p,Progress::Complete){break;}assert!(matches!(p,Progress::Partial{..}));assert!(calls<160);}Ok(calls)}
fn read_events(rt:&mut Runtime,e:&Epoch,expected:usize,cap:usize)->anyhow::Result<Value>{let end=Instant::now()+Duration::from_secs(5);let(mut count,mut reads,mut socket_bytes,mut max_queued,mut max_batch)=(0,0,0,0,0);while count<expected{assert!(Instant::now()<end);let s=rt.read_source_loopback_step(e,cap)?;reads+=1;socket_bytes+=s.socket_bytes;assert!(!s.eof);if let Some(b)=s.batch{assert!(b.terminal.is_none());max_batch=max_batch.max(b.events.len());assert!(b.events.len()<=8);count+=b.events.len();}max_queued=max_queued.max(rt.source_loopback_snapshot().unwrap().queued_rx_bytes);}assert_eq!(count,expected);Ok(json!({"events":count,"read_calls":reads,"actual_socket_bytes":socket_bytes,"max_queued_tail":max_queued,"max_batch_events":max_batch}))}
